"""Registered analyses for Part A (see preregistration/E13_DEMO_CONFORMANCE.md). Usage: python analyze_mutation_eval.py <csv> [out_md]"""
import math, os, random, sys
from pathlib import Path
import numpy as np, pandas as pd
sys.path.insert(0, str(Path(__file__).resolve().parent)); import locate, mutate
W = mutate.W
DB = next((W / "../scans/704cb35f0/chocolate-doom").resolve().glob("*master.db")); G = locate.CallGraph(DB)
U = {n for n, (p, l) in G.where.items() if any(p.endswith(f"src/doom/{s}.c") for s in mutate.FILES)}; NU = len(U)

def wilson(k, n, z=1.96):
    if n == 0: return (float("nan"),) * 2
    p = k / n; d = 1 + z * z / n; c = (p + z * z / (2 * n)) / d; h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d; return c - h, c + h

def cluster_boot(df, col, B=2000, seed=1):
    """bootstrap CI for the mean of a 0/1 (or numeric) column, resampling the mutated function as the cluster"""
    rng = random.Random(seed); groups = [g[col].astype(float).tolist() for _, g in df.groupby("truth")]
    if not groups: return (float("nan"),) * 2
    ms = []
    for _ in range(B):
        s = [x for g in (rng.choice(groups) for _ in groups) for x in g]; ms.append(sum(s) / len(s))
    ms.sort(); return ms[int(0.025 * B)], ms[int(0.975 * B)]

def mcnemar(b, c):
    n = b + c
    if n == 0: return 1.0
    k = min(b, c); p = sum(math.comb(n, i) for i in range(0, k + 1)) / 2 ** n; return min(1.0, 2 * p)

def hit(df, prefix, d):
    t = pd.to_numeric(df[f"{prefix}_truth_depth"], errors="coerce"); return (t <= d).astype(int)

def main():
    df = pd.read_csv(sys.argv[1]); out = []; P = out.append
    P("# E13 Part A results: localiser validity on injected bugs\n"); P(f"Generated by `analyze_mutation_eval.py` from `{Path(sys.argv[1]).name}`. Universe |U| = {NU} functions in the 16 mutated files; whole call graph {G.total} functions.\n")
    st = df.status.value_counts(); P("## Mutant outcomes\n"); P(st.to_frame("mutants").to_markdown() + "\n")
    buildable = df[df.status != "does not build"]; killed = df[df.status == "killed"].copy()
    k1, n1 = len(killed), len(buildable); lo, hi = wilson(k1, n1)
    P(f"**M1 (detection rate among buildable mutants):** {k1}/{n1} = {k1 / max(n1, 1):.1%} (Wilson 95% {lo:.1%} to {hi:.1%}).\n")
    for col in ("file", "kind"):
        t = buildable.groupby(col).apply(lambda g: pd.Series({"buildable": len(g), "killed": int((g.status == "killed").sum()), "rate": (g.status == "killed").mean()}), include_groups=False); P(f"Detection by {col}:\n\n" + t.round(2).to_markdown() + "\n")
    if k1 == 0: Path(sys.argv[2] if len(sys.argv) > 2 else "/dev/stdout").write_text("\n".join(out)); return
    for d in (1, 2, 3, 6): killed[f"hitA{d}"] = hit(killed, "A", d); killed[f"hitB{d}"] = hit(killed, "B", d)
    killed["triv"] = (pd.to_numeric(killed["A_truth_depth"], errors="coerce") == 0).astype(int)
    P("## Hit rates (variant A = callees of the symptom functions; variant B also seeds with callers up to 2 levels), earliest-diverging demo\n")
    rows = []
    for v in ("A", "B"):
        for d in (1, 2, 3, 6):
            h = killed[f"hit{v}{d}"]; lo, hi = wilson(int(h.sum()), len(h)); cl, ch = cluster_boot(killed, f"hit{v}{d}"); rows.append((v, d, f"{h.sum()}/{len(h)}", f"{h.mean():.1%}", f"{lo:.1%}-{hi:.1%}", f"{cl:.1%}-{ch:.1%}"))
    P(pd.DataFrame(rows, columns=["variant", "depth<=", "hits", "rate", "Wilson 95%", "cluster-bootstrap 95%"]).to_markdown(index=False) + "\n")
    P("## Stratified by how the mutated function relates to the RNG-caller symptoms (A, depth <= 3)\n")
    s = killed.groupby("triv").apply(lambda g: pd.Series({"mutants": len(g), "hit@3": g["hitA3"].mean()}), include_groups=False).rename(index={0: "mutated function is NOT itself a symptom (non-trivial)", 1: "mutated function is itself a symptom (depth 0)"}); P(s.round(3).to_markdown() + "\n")
    s2 = killed.groupby("truth_calls_prandom").apply(lambda g: pd.Series({"mutants": len(g), "hit@3": g["hitA3"].mean()}), include_groups=False); P("By whether the mutated function calls the RNG directly (static call graph):\n\n" + s2.round(3).to_markdown() + "\n")
    nt = killed[killed.triv == 0]
    P(f"**Non-trivial subset (primary for P2):** {len(nt)} mutants; A depth<=3 hit rate {nt['hitA3'].mean():.1%}; depth<=6 {nt['hitA6'].mean():.1%}.\n")
    P("## Narrowing and baselines (A, depth <= 3)\n")
    killed["A3"] = killed["A_size_3"]; killed["exp_random"] = (killed["A3"] / NU).clip(upper=1.0)
    P(f"Suspect-set size at depth 3: median {killed.A3.median():.0f} functions ({killed.A3.median() / NU:.1%} of |U|; {killed.A3.median() / G.total:.1%} of the whole graph); quartiles {killed.A3.quantile(.25):.0f} to {killed.A3.quantile(.75):.0f}; max {killed.A3.max():.0f}.\n")
    base = pd.DataFrame({"baseline": ["observed hit rate (A, <=3)", "random suspects, same size, from U (expected)", "degree-preserving rewired call graph (null)", "field-family prior (same mutants)"],
                         "hit rate": [killed.hitA3.mean(), killed.exp_random.mean(), killed.rewired_hit_3.mean(), killed.ff_hit_3.mean()],
                         "mean suspects": [killed.A3.mean(), killed.A3.mean(), killed.rewired_size_3.mean(), killed.ff_size_3.mean()]}); P(base.round(3).to_markdown(index=False) + "\n")
    lift = (killed.hitA3 - killed.exp_random); lo, hi = cluster_boot(killed.assign(lift=lift), "lift"); P(f"Lift over random same-size suspects: {lift.mean():+.3f} (cluster-bootstrap 95% {lo:+.3f} to {hi:+.3f}). Lift over the rewired null: {(killed.hitA3 - killed.rewired_hit_3).mean():+.3f}.\n")
    b = int(((killed.hitA3 == 1) & (killed.ff_hit_3 == 0)).sum()); c = int(((killed.hitA3 == 0) & (killed.ff_hit_3 == 1)).sum()); P(f"A(<=3) versus the field-family prior on the same mutants: only-A {b}, only-prior {c}, McNemar exact p = {mcnemar(b, c):.3f}.\n")
    P("## RNG-caller basis versus fallback (M5)\n"); killed["rngbasis"] = (killed.basis == "rng-caller diff").astype(int)
    P(f"RNG-caller basis available in {killed.rngbasis.sum()}/{len(killed)} = {killed.rngbasis.mean():.1%} of detected mutants.\n")
    r = killed[killed.rngbasis == 1]; b = int(((r.hitA3 == 1) & (r.ff_hit_3 == 0)).sum()); c = int(((r.hitA3 == 0) & (r.ff_hit_3 == 1)).sum())
    P(f"On the mutants with an RNG basis (paired): A hit@3 {r.hitA3.mean():.1%} vs field prior {r.ff_hit_3.mean():.1%} (only-A {b}, only-prior {c}, McNemar p = {mcnemar(b, c):.3f}). Mutants without an RNG basis: {len(killed) - len(r)}; their field-prior hit@3 {killed[killed.rngbasis == 0].ff_hit_3.mean():.1%} (different kind of mutant; not comparable).\n")
    P("## Variant B versus A at matched suspect-set size\n")
    def matched(row):
        ta = pd.to_numeric(row["B_truth_depth"], errors="coerce")
        if pd.isna(ta): return 0
        best = -1
        for d in range(0, 7):
            if row[f"B_size_{d}"] <= row["A_size_3"]: best = d
        return int(best >= 0 and ta <= best)
    killed["hitB_matched"] = killed.apply(matched, axis=1); b = int(((killed.hitB_matched == 1) & (killed.hitA3 == 0)).sum()); c = int(((killed.hitB_matched == 0) & (killed.hitA3 == 1)).sum())
    P(f"B restricted to the largest depth whose size does not exceed A's depth-3 size: hit rate {killed.hitB_matched.mean():.1%} vs A {killed.hitA3.mean():.1%} (only-B {b}, only-A {c}, McNemar p = {mcnemar(b, c):.3f}). Unmatched B (<=3): {killed.hitB3.mean():.1%} with median size {killed.B_size_3.median():.0f}.\n")
    P("## Misses: not reachable versus too deep (A)\n"); miss = killed[killed.hitA6 == 0]
    P(f"Of {len(miss)} mutants whose truth is not within depth 6: statically unreachable from the symptoms at any depth: {int((miss.reachable_any == 0).sum())}; reachable but deeper than 6: {int((miss.reachable_any == 1).sum())}. Truth reachable at any depth overall: {killed.reachable_any.mean():.1%}.\n")
    P("## Sensitivity to the choice of failing demo (A, depth <= 3)\n")
    rows = []
    for pre, nm in (("", "earliest"), ("random_", "random failing demo"), ("median_", "median failing demo")):
        if f"{pre}A_truth_depth" in killed: h = (pd.to_numeric(killed[f"{pre}A_truth_depth"], errors="coerce") <= 3).astype(int); rows.append((nm, f"{h.mean():.1%}", f"{killed[f'{pre}A_size_3'].median():.0f}"))
    P(pd.DataFrame(rows, columns=["demo choice", "hit@3", "median size@3"]).to_markdown(index=False) + "\n")
    allb = len(buildable); P(f"## Survivor sensitivity\nIf every surviving or crashing mutant were counted as a localiser miss, the depth<=3 hit rate over all {allb} buildable mutants would be {killed.hitA3.sum()}/{allb} = {killed.hitA3.sum() / max(allb, 1):.1%} (a different quantity: it mixes detection with localisation).\n")
    P("## Registered predictions (thresholds exactly as in preregistration/E13_DEMO_CONFORMANCE.md, section A)\n")
    nt3 = nt["hitA3"].mean() if len(nt) else float("nan"); med = killed.A3.median() / NU; lo, hi = wilson(int(killed.hitA3.sum()), len(killed)); l3, h3 = cluster_boot(killed.assign(lift=lift), "lift")
    ntk = killed[killed.triv == 0]; ntlift = (ntk["hitA3"] - ntk["exp_random"]).mean() if len(ntk) else float("nan")
    rr = killed[killed.rngbasis == 1]; pr = (rr.hitA3.mean() - rr.ff_hit_3.mean()) * 100 if len(rr) else float("nan"); rw = (killed.hitA3.mean() - killed.rewired_hit_3.mean()) * 100
    rnd = pd.to_numeric(killed["random_A_truth_depth"], errors="coerce").le(3).mean() if "random_A_truth_depth" in killed else float("nan"); p7 = abs(rnd - killed.hitA3.mean()) * 100
    rows = [("M1 (descriptive)", "killed share of buildable mutants within 20% to 55%", f"{k1 / max(n1, 1):.1%}", "within band" if 0.20 <= k1 / max(n1, 1) <= 0.55 else "outside band"),
            ("P1 (primary)", "A hit@3 >= 50% AND lift over random >= +20 points (cluster 95% lower bound > 0)", f"hit {killed.hitA3.mean():.1%} (Wilson {lo:.1%}-{hi:.1%}); lift {lift.mean() * 100:+.1f} points (cluster {l3 * 100:+.1f} to {h3 * 100:+.1f})", "PASSED" if killed.hitA3.mean() >= 0.5 and lift.mean() >= 0.20 and l3 > 0 else "FAILED"),
            ("P2 (primary)", "non-trivial subset: hit@3 >= 35% AND lift >= +15 points", f"hit {nt3:.1%}; lift {ntlift * 100:+.1f} points", "PASSED" if nt3 >= 0.35 and ntlift >= 0.15 else "FAILED"),
            ("P3", "median depth-3 suspect set <= 30% of |U|", f"{med:.1%} of |U|", "PASSED" if med <= 0.30 else "FAILED"),
            ("P4 (exploratory)", "variant B vs A at matched size: report only", f"B matched {killed.hitB_matched.mean():.1%} vs A {killed.hitA3.mean():.1%}", "reported"),
            ("P5a", "RNG-caller difference exists for >= 70% of killed mutants", f"{killed.rngbasis.mean():.1%}", "PASSED" if killed.rngbasis.mean() >= 0.70 else "FAILED"),
            ("P5b (primary)", "on RNG-basis mutants, A hit@3 exceeds the field prior by >= 15 points (paired)", f"{pr:+.1f} points", "PASSED" if pr >= 15 else "FAILED"),
            ("P6", "A hit@3 exceeds the rewired-graph null's mean by >= 20 points", f"{rw:+.1f} points", "PASSED" if rw >= 20 else "FAILED"),
            ("P7", "random failing demo hit@3 within 10 points of the earliest demo's", f"{p7:.1f} points apart", "PASSED" if p7 <= 10 else "FAILED")]
    P(pd.DataFrame(rows, columns=["prediction", "registered", "observed", "result"]).to_markdown(index=False) + "\n")
    Path(sys.argv[2] if len(sys.argv) > 2 else "/dev/stdout").write_text("\n".join(out)); print("\n".join(out)[:300]) if len(sys.argv) > 2 else None

if __name__ == "__main__": main()
